const WebSocketImpl = require('"'"'ws'"'"');
const token = process.env.OPENCLAW_GATEWAY_TOKEN || process.env.MOSAIC_OPENCLAW_GATEWAY_TOKEN || '"'"''"'"';
const url = process.env.MOSAIC_OPENCLAW_GATEWAY_URL || '"'"'ws://openclaw:18789'"'"';
const protocol = Number(process.env.MOSAIC_OPENCLAW_PROTOCOL || '"'"'4'"'"');
const method = process.env.OC_GATEWAY_METHOD || '"'"''"'"';
const params = JSON.parse(process.env.OC_GATEWAY_PARAMS || '"'"'{}'"'"');
const ws = new WebSocketImpl(url);
const pending = new Map();
let seq = 0;
let connected = false;
let timer;
function payload(frame) {
  return frame && typeof frame === '"'"'object'"'"' && '"'"'payload'"'"' in frame ? frame.payload : frame;
}
function request(name, body) {
  const id = '"'"'mosaic-ui-'"'"' + (++seq);
  const promise = new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  ws.send(JSON.stringify({ type: '"'"'req'"'"', id, method: name, params: body || {} }));
  return promise;
}
function fail(error) {
  clearTimeout(timer);
  process.stderr.write(String(error && error.stack || error));
  try { ws.close(); } catch {}
  process.exitCode = 1;
}
timer = setTimeout(() => fail(new Error(method + '"'"' timed out'"'"')), Number(process.env.OC_GATEWAY_TIMEOUT_MS || '"'"'90000'"'"'));
ws.onopen = async () => {
  try {
    await request('"'"'connect'"'"', {
      minProtocol: protocol,
      maxProtocol: protocol,
      client: { id: '"'"'openclaw-tui'"'"', displayName: '"'"'Operations UI'"'"', version: '"'"'1.0.0'"'"', platform: process.platform, mode: '"'"'ui'"'"' },
      role: '"'"'operator'"'"',
      scopes: ['"'"'operator.read'"'"', '"'"'operator.write'"'"', '"'"'operator.admin'"'"', '"'"'operator.approvals'"'"'],
      caps: ['"'"'tool-events'"'"'],
      auth: { token },
    });
    connected = true;
    const result = await request(method, params);
    clearTimeout(timer);
    process.stdout.write(JSON.stringify(result));
    ws.close();
  } catch (error) {
    fail(error);
  }
};
ws.onmessage = (event) => {
  let frame;
  try { frame = JSON.parse(typeof event.data === '"'"'string'"'"' ? event.data : String(event.data)); } catch { return; }
  if (!frame || typeof frame !== '"'"'object'"'"' || frame.type !== '"'"'res'"'"' || typeof frame.id !== '"'"'string'"'"') return;
  const match = pending.get(frame.id);
  if (!match) return;
  pending.delete(frame.id);
  if (frame.ok === true) match.resolve(payload(frame));
  else match.reject(new Error(frame.error && frame.error.message || '"'"'gateway request failed'"'"'));
};
ws.onerror = () => fail(new Error('"'"'gateway websocket error'"'"'));
ws.onclose = () => {
  if (!connected && pending.size) fail(new Error('"'"'gateway websocket closed before connect'"'"'));
